inputs.expression:
(
    /* Collect the list of search results returned from 'Search_TI_Records' for all observables. */
    $search_results := [actions.ForEach_Observable.result.'Search_TI_Records'.result.records];

    /* Get the list of observable values that were input. */
    $observables := inputs.Observable_Values;

    /* Filter the search results to only those that have a 'threat-intelligence-verdict' field. */
    $search_results_for_verdict := $filter(
        $search_results, 
        function($v) { $exists($v.'threat-intelligence-verdict') }
    );

    /* Determine the overall verdict by prioritizing verdicts in the order: */
    /* malicious > suspicious > benign > unknown. */
    /* If none exist, default to 'Unknown'. */
    $verdict := ([
        /* Find any verdicts marked as 'malicious' */
        $search_results_for_verdict[
            $lowercase($.'threat-intelligence-verdict' ? $.'threat-intelligence-verdict' : "unknown") = "malicious"
        ],
        /* Find any verdicts marked as 'suspicious' */
        $search_results_for_verdict[
            $lowercase($.'threat-intelligence-verdict' ? $.'threat-intelligence-verdict' : "unknown") = "suspicious"
        ],
        /* Find any verdicts marked as 'benign' */
        $search_results_for_verdict[
            $lowercase($.'threat-intelligence-verdict' ? $.'threat-intelligence-verdict' : "unknown") = "benign"
        ],
        /* Find any verdicts marked as 'unknown' */
        $search_results_for_verdict[
            $lowercase($.'threat-intelligence-verdict' ? $.'threat-intelligence-verdict' : "unknown") = "unknown"
        ],
        /* If none of the above, insert a fallback object with verdict 'Unknown' */
        {
            "threat-intelligence-verdict": "Unknown"
        }
    ])[0].'threat-intelligence-verdict'; /* Take the first matching verdict. */

    {
        /* Check if enrichment is "complete" by comparing the observable count to the count of search results with a verdict. */
        "enrichment_complete": $count($observables) = $count($search_results[$.'threat-intelligence-verdict']),

        /* The determined verdict value. */
        "verdict": $verdict,

        /* Classify the verdict as "True Positive" or "False Positive" based on verdict value. */
        "classification": $lookup({
            "malicious": "True Positive",
            "suspicious": "True Positive",
            "benign": "False Positive",
            "unknown": "Unknown"
        }, $lowercase($verdict)),

        /* Gather list of all 'tracking-id' values from the search results. */
        "ti_record_tracking_ids": [
            $search_results.'tracking-id'
        ],

        /* Get the highest 'turbine-risk-score' among all search results. */
        "turbine_risk_score": $max([$search_results.'turbine-risk-score'])
    }
)
